import itertools
from collections import Counter


def _temporal(data, coupon_rule, minimum_duration):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit.get(data["source"], 0)
    coupons = data["coupons"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    # State includes every resource that can affect future feasibility.
    start_state = (data["source"], initial_mask, 0)
    best = {start_state: data["start"]}
    queue = [(data["start"], data["source"], initial_mask, 0)]
    while queue:
        arrival, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if best.get(state) != arrival:
            continue
        if node == data["target"] and mask == full and (
                coupon_rule == "at_most" or used == coupons):
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < coupons:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, next_used in options:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if next_time < best.get(next_state, float("inf")):
                    best[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node,
                                           next_mask, next_used))
    return {"arrival": None}


def _build_component_01():
    return lambda data: _temporal(data, "exact", 1)


def _build_component_02():
    return lambda data: _temporal(data, "at_most", 2)


def _build_component_03():
    return lambda data: _temporal(data, "exact", 2)


def _build_component_04():
    return lambda data: _temporal(data, "at_most", 1)


def _build_component_05():
    return lambda data: _temporal(data, "exact", 1)


def _round(numerator, denominator, mode):
    if mode == "half_up":
        return (numerator + denominator // 2) // denominator
    return numerator // denominator


def _build_component_06():
    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = _round(raw * (10000 - discount), 10000, mode)
            tax = _round(net * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            account = event.get("account", "default")
            currency = event.get("currency", "USD")
            key = account + "|" + currency
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        domains = []
        for name in names:
            versions = [row["version"] for row in packages[name]
                        if row["version"] not in blocked.get(name, [])
                        and (name not in pins or row["version"] == pins[name])]
            domains.append([-1] + sorted(versions))

        best_vector = None
        best_assignment = None
        for values in itertools.product(*domains):
            assignment = {name: value for name, value in zip(names, values)
                          if value != -1}
            valid = True
            for name, bounds in roots.items():
                value = assignment.get(name)
                if value is None or not bounds[0] <= value <= bounds[1]:
                    valid = False
                    break
            if not valid:
                continue

            rows_by_version = {
                name: {row["version"]: row for row in rows}
                for name, rows in packages.items()
            }
            edges = {}
            for name, version in assignment.items():
                row = rows_by_version[name][version]
                deps = [dep for dep in row.get("deps", [])
                        if not dep.get("feature") or dep["feature"] in features]
                edges[name] = []
                for dep in deps:
                    target = dep["name"]
                    target_version = assignment.get(target)
                    if (target_version is None
                            or not dep["min"] <= target_version <= dep["max"]):
                        valid = False
                        break
                    edges[name].append(target)
                if not valid:
                    break
            if not valid:
                continue

            # Installed packages must be precisely the active closure of roots.
            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges.get(name, []))
            if reachable != set(assignment):
                continue

            done, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges.get(name, [])):
                    return False
                active.remove(name)
                done.add(name)
                return True

            if not all(visit(name) for name in assignment):
                continue
            if best_vector is None or values > best_vector:
                best_vector = values
                best_assignment = assignment

        if best_assignment is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_assignment}
    return solve


def _build_component_08():
    def solve(data):
        jobs = [job for job in data["jobs"]
                if job["id"] not in data.get("blocked", [])]
        k = data["k"]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        for subset in itertools.combinations(jobs, k):
            ids = {job["id"] for job in subset}
            if not mandatory.issubset(ids):
                continue
            counts = Counter(job["group"] for job in subset)
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            # At most two intervals can be active at any point; touching is OK.
            active_ends = []
            fits = True
            for job in sorted(subset, key=lambda item: (item["start"], item["end"])):
                while active_ends and active_ends[0] <= job["start"]:
                    heapq.heappop(active_ends)
                heapq.heappush(active_ends, job["end"])
                if len(active_ends) > 2:
                    fits = False
                    break
            if not fits:
                continue

            value = sum(job["value"] for job in subset)
            sorted_ids = tuple(sorted(ids))
            if (best_value is None or value > best_value
                    or (value == best_value and sorted_ids > best_ids)):
                best_value, best_ids = value, sorted_ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


